; ==================================================================
; ENTITY DEFINITIONS
; ==================================================================

; Entity: tpl_msx_basic_patrol_enemy_instance (instance from template: tpl_msx_basic_patrol_enemy)
ENTITY_TPL_MSX_BASIC_PATROL_ENEMY_INSTANCE_ID EQU 0
ENTITY_TPL_MSX_BASIC_PATROL_ENEMY_INSTANCE_COMP_MASK EQU #8CF  ; Component mask: 100011001111b
; Template: tpl_msx_basic_patrol_enemy
ENTITY_TPL_MSX_BASIC_PATROL_ENEMY_INSTANCE_X EQU 4
ENTITY_TPL_MSX_BASIC_PATROL_ENEMY_INSTANCE_Y EQU 10

; ==================================================================
; ENTITY MANAGEMENT FUNCTIONS
; ==================================================================

init_entities:
    ; Initialize all active game entities (1 entities)

    ; Ensure sprite system is reset whenever entities are initialized
    call init_sprites
    call init_player_fast_runtime

    ; CRITICAL: Clear ALL entity component masks to prevent ghost entities
    ; RAM may contain random data - entities 0..N will be set by create_entity
    ld hl, entity_comp_masks
    ld de, entity_comp_masks+1
    ld bc, 31                  ; Clear 32 bytes (32-1 for LDIR)
    ld (hl), 0
    ldir

    ld hl, entity_comp_masks_hi
    ld de, entity_comp_masks_hi+1
    ld bc, 31
    ld (hl), 0
    ldir

    ; Clear entity screen IDs to prevent ghost entities on restart
    ld hl, entity_screen_id
    ld de, entity_screen_id+1
    ld bc, 31
    ld (hl), 0
    ldir

    ; Clear entity player-role flags
    ld hl, entity_is_player
    ld de, entity_is_player+1
    ld bc, 31
    ld (hl), 0
    ldir

    ; Clear entity template tokens
    ld hl, entity_template_token
    ld de, entity_template_token+1
    ld bc, 31
    ld (hl), 0
    ldir

    ; Clear facing-direction cache so first-frame ChangeSprite does not
    ; redirect through stale RAM garbage from a previous run/screen.
    ld hl, entity_facing_dir
    ld de, entity_facing_dir+1
    ld bc, 31
    ld (hl), 0
    ldir
    
    ; Initialize State Machine variables (Clear to 0)
    ld hl, entity_sm_ptr_l
    ld de, entity_sm_ptr_l+1
    ld bc, 31
    ld (hl), 0
    ldir

    ld hl, entity_sm_ptr_h
    ld de, entity_sm_ptr_h+1
    ld bc, 31
    ld (hl), 0
    ldir

    ld hl, entity_sm_timer_l
    ld de, entity_sm_timer_l+1
    ld bc, 31
    ld (hl), 0
    ldir

    ld hl, entity_sm_timer_h
    ld de, entity_sm_timer_h+1
    ld bc, 31
    ld (hl), 0
    ldir

    ld hl, entity_sm_wait_timer
    ld de, entity_sm_wait_timer+1
    ld bc, 31
    ld (hl), 0
    ldir

    ld hl, entity_sm_sprite_control
    ld de, entity_sm_sprite_control+1
    ld bc, 31
    ld (hl), 0
    ldir
    
    call init_tpl_msx_basic_patrol_enemy_instance
    call init_player_from_hero_entity
    ret

update_entities:
    ; Update all active entities (1 entities)
    ; Skip entity update if entity belongs to another screen
    ld hl, entity_screen_id + 0
    ld a, (hl)
    ld hl, current_screen_id
    cp (hl)
    jr nz, .skip_update_0
    ; Run per-entity update
    call update_tpl_msx_basic_patrol_enemy_instance
.skip_update_0:
    ret

init_tpl_msx_basic_patrol_enemy_instance:
    ; Initialize tpl_msx_basic_patrol_enemy_instance at real position from JSON
    ; JSON position: (4, 10) tiles = (32, 80) pixels
    ; Template: tpl_msx_basic_patrol_enemy
    ; Components: Position, Sprite, Movement, Collision, Health, Animation
    ; Direction mask: #0F (1111b) = All directions

    ; Set entity ID and component mask (DYNAMIC - based on template)
    ; Mask is 16-bit: B=low byte, C=high byte
    ld a, 0             ; Entity ID
    ld b, #CF              ; Mask low byte
    ld c, #08              ; Mask high byte
    call create_entity         ; Create with actual components from template

    ; Configure per-entity job cadence
    ; period: 1 frame(s), entry: 0
    ld a, 0
    ld b, 1
    ld c, 0
    call entity_job_set

    ; Set real position from JSON data
    ld hl, entity_x_pos
    ld e, 0             ; Entity index
    ld d, 0
    add hl, de
    ld (hl), 32         ; Set real X position from JSON

    ld hl, entity_y_pos
    add hl, de
    ld (hl), 80         ; Set real Y position from JSON

    ; Set entity screen ID (for multi-screen support)
    ld hl, entity_screen_id
    add hl, de
    ld (hl), 0                 ; Screen ID (world node index / fallback screen index)

    ld hl, entity_is_player
    add hl, de
    ld (hl), 0                 ; Player/hero marker from template

    ; Template token for state-machine template-aware actions
    ld hl, entity_template_token
    add hl, de
    ld (hl), 11

    ; Mark whether this entity's state machine actually owns sprite changes.
    ; Plain state machines without ChangeSprite should keep auto-facing active.
    ld hl, entity_sm_sprite_control
    add hl, de
    ld (hl), 0



    ; Initialize Animation component
    ld hl, entity_anim_frame
    add hl, de
    ld (hl), #00           ; currentFrameIndex

    ld hl, entity_anim_tick
    add hl, de
    ld (hl), 0                ; tick counter

    ld hl, entity_anim_speed
    add hl, de
    ld (hl), #0A           ; animationSpeed

    ld hl, entity_anim_flags
    add hl, de
    ld (hl), #07           ; flags (playing/loop/onlyWhenMoving)


    ; === Patrol Component Init ===
    ; Waypoints: (64, 120) -> (160, 120)
    ; Override position with waypoint1
    ld hl, entity_x_pos
    add hl, de
    ld (hl), 64         ; Start X = waypoint1_x

    ld hl, entity_y_pos
    add hl, de
    ld (hl), 120         ; Start Y = waypoint1_y

    ; Set patrol velocity
    ld hl, entity_vel_x
    add hl, de
    ld (hl), 1           ; VelX = +1

    ld hl, entity_vel_y
    add hl, de
    ld (hl), 0           ; VelY = +0


    ; Initialize Collision component (hitbox + layer masks)
    ld hl, entity_collision_hitbox_w
    add hl, de
    ld (hl), #0C      ; hitboxWidth

    ld hl, entity_collision_hitbox_h
    add hl, de
    ld (hl), #0E      ; hitboxHeight

    ld hl, entity_collision_offset_x
    add hl, de
    ld (hl), #02      ; offsetX (2)

    ld hl, entity_collision_offset_y
    add hl, de
    ld (hl), #01      ; offsetY (1)

    ld hl, entity_collision_layer
    add hl, de
    ld (hl), #02      ; collisionLayer

    ld hl, entity_collides_with
    add hl, de
    ld (hl), #05      ; collidesWith


    ; Initialize Health component
    ld hl, entity_health_current
    add hl, de
    ld (hl), #01      ; current health

    ld hl, entity_health_max
    add hl, de
    ld (hl), #01      ; max health



    ; Initialize Damage component
    ld hl, entity_damage_amount
    add hl, de
    ld (hl), #01      ; damage amount




    ; Set sprite pattern and color (renderable entity)
    ld hl, sprite_pattern
    add hl, de
    ld (hl), 0          ; Use entity index * 4 for 16x16 sprites

    ld hl, sprite_color
    add hl, de
    ld (hl), 2                ; Distinct color for debugging


    ; Set direction mask for Cursors component (if entity has Input component)
    ld hl, entity_dir_mask
    add hl, de
    ld (hl), #0F            ; Direction restrictions: All directions

    ; Set input speed for Cursors component (if entity has Input component)
    ld hl, entity_input_speed
    add hl, de
    ld (hl), 2            ; Cursor speed (px/frame)


    ; Force update sprite attributes only if entity is in current screen
    ld hl, entity_screen_id + 0
    ld a, (hl)
    ld hl, current_screen_id
    cp (hl)
    jr nz, .skip_force_show_0

    ; Force update sprite attributes (using correct multi-layer config)
    ld c, 0             ; Entity Index
    call force_update_entity_sprite
.skip_force_show_0:



    ret

update_tpl_msx_basic_patrol_enemy_instance:
    ; Update tpl_msx_basic_patrol_enemy_instance - Patrol bounce
    ; Waypoints: (64, 120) -> (160, 120)
    ld e, 0             ; Entity index
    ld d, 0

    ; --- X axis bounce ---
    ld hl, entity_vel_x
    add hl, de
    ld a, (hl)
    or a
    jp z, .patrol_end_0
    bit 7, a
    jp nz, .patrol_chk_min_x_0

    ; Moving right: x >= 160?
    ld hl, entity_x_pos
    add hl, de
    ld a, (hl)
    cp 160
    jp c, .patrol_end_0
    ; Bounce: negate vel_x
    ld hl, entity_vel_x
    add hl, de
    ld a, (hl)
    neg
    ld (hl), a
    jp .patrol_end_0

.patrol_chk_min_x_0:
    ; Moving left: x <= 64?
    ld hl, entity_x_pos
    add hl, de
    ld a, (hl)
    cp 65
    jp nc, .patrol_end_0
    ; Bounce: negate vel_x
    ld hl, entity_vel_x
    add hl, de
    ld a, (hl)
    neg
    ld (hl), a

.patrol_end_0:
    ; Sync sprite facing with current patrol velocity
    call update_entity_patrol_facing
    ret

